-- Phase 28 spec, D7: a page slot (e.g. home.hero) holds at most one MediaItem, so a replace that
-- races another fails on the index instead of leaving two rows. Gallery owners keep many rows.
-- Declared in schema.prisma through the partialIndexes preview feature, so migrate keeps it, and
-- generated by `prisma migrate diff` (migrate dev's duplicate-values prompt can't be answered in
-- a non-interactive shell). Additive; MediaItem had no PAGE rows.

-- CreateIndex
CREATE UNIQUE INDEX "MediaItem_page_slot_key" ON "MediaItem"("ownerId") WHERE ("ownerType" = 'PAGE');
